const initial={restaurant:{name:'Saffron Table',slug:'saffron-table',currency:'₹',hero:'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=85'},scanCount:128,today:24,menu:[{name:'Small Plates',items:[{name:'Crispy Corn Chaat',description:'Sweet corn, lime, chilli, coriander',price:'220',tag:'crowd favourite',image:'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=300&q=80',available:true},{name:'Charred Paneer',description:'Smoky paneer, mint yoghurt',price:'310',tag:'vegetarian',image:'https://images.unsplash.com/photo-1567188040759-fb8a883dc6d8?auto=format&fit=crop&w=300&q=80',available:true}]},{name:'Mains',items:[{name:'Butter Chicken',description:'Tomato, kasuri methi, cream',price:'420',tag:'house favourite',image:'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=300&q=80',available:true},{name:'Vegetable Biryani',description:'Aromatic basmati, seasonal vegetables',price:'360',tag:'seasonal',image:'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=300&q=80',available:false}]}]};
let state=JSON.parse(localStorage.getItem('menuquo-demo')||'null')||structuredClone(initial),view=location.hash.slice(1)||'landing';
const $=s=>document.querySelector(s),save=()=>localStorage.setItem('menuquo-demo',JSON.stringify(state)),money=x=>state.restaurant.currency+Number(x).toLocaleString('en-IN');
function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2200)}function go(v){location.hash=v;view=v;render();scrollTo(0,0)}
function landing(){return `<div class="shell"><header class="topbar"><a class="brand" href="#landing"><span class="brand-mark">m</span>menuquo</a><nav class="nav"><a href="#landing">Product</a><a href="#sales">For restaurants</a><a href="#login">Log in</a><button class="btn" data-go="login">Start free</button></nav></header><main><section class="hero"><span class="eyebrow"><i></i> Built for independent restaurants</span><h1>A menu worth <em>scanning.</em></h1><p>Menuquo turns your restaurant menu into a fast, beautiful QR experience—so you can update in seconds, not reprint for weeks.</p><div class="hero-actions"><button class="btn dark" data-go="login">Create your menu →</button><button class="btn ghost" data-go="public">See a live menu</button></div></section><section class="product-shot"><div class="browser"><div class="browser-top"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span class="address"></span></div><div class="shot-body"><aside class="shot-side"><b>menuquo</b><span>▦ Overview</span><span>☰ Menu editor</span><span>⌘ QR codes</span><span>⚙ Settings</span></aside><div class="shot-main"><h3>Good morning, Saffron Table</h3><p>Here’s what your menu is doing today.</p><div class="metrics"><div class="metric"><span>Menu scans</span><strong>128</strong></div><div class="metric"><span>Today</span><strong>24</strong></div><div class="metric"><span>Live items</span><strong>4</strong></div></div><div class="chart">${[35,62,48,82,69,95,58,79,100,73,88,55].map(x=>`<i class="bar" style="height:${x}%"></i>`).join('')}</div></div></div></div></section><section class="section"><div class="section-head"><span class="eyebrow">Less printing. More hospitality.</span><h2>Everything your menu needs. Nothing it doesn’t.</h2><p>A focused set of tools for restaurant owners who want a polished digital menu without a complicated system.</p></div><div class="cards"><article class="card icon-yellow"><span class="icon-box">✦</span><h3>Instant updates</h3><p>Change a price or mark an item sold out. Your guests see the update immediately.</p></article><article class="card"><span class="icon-box">⌘</span><h3>QR codes that work</h3><p>Generate, download, and print a clean QR code that sends guests straight to your menu.</p></article><article class="card"><span class="icon-box">↗</span><h3>Clear scan insights</h3><p>Know when your menu is being viewed and see simple daily scan trends.</p></article></div></section><section class="split-banner"><div class="banner"><div class="banner-copy"><span class="eyebrow">Made for the table</span><h2>Your menu, in your guests’ hands.</h2><p>No app download. No clutter. Just a responsive menu that loads quickly on any phone.</p><button class="btn" data-go="public">Open sample menu</button></div><div class="menu-card"><h3>Saffron Table</h3><div class="dish"><span>Crispy Corn Chaat</span><b>₹220</b></div><div class="dish"><span>Butter Chicken</span><b>₹420</b></div><div class="dish"><span>Vegetable Biryani</span><b>₹360</b></div></div></div></section><section class="sales" id="sales"><div class="sales-grid"><article class="sales-card"><span class="eyebrow">Sales message</span><h3>A concise outreach pitch</h3><p class="quote">“A cleaner menu experience, without the cost and hassle of reprinting.”</p><p>Menuquo helps restaurants publish a mobile-friendly QR menu, make real-time updates, and understand when guests engage—all from one simple dashboard.</p><button class="btn" data-copy="Hi [Name], we’re inviting a small number of restaurants to try Menuquo—a fast QR menu that lets you update prices and sold-out items instantly, without reprinting. Would you be open to a 10-minute demo this week?">Copy outreach message</button></article><article class="sales-card dark"><span class="eyebrow">Pilot offer</span><h3>Founding restaurant pilot</h3><ul><li>Free menu setup and QR code design</li><li>Seven-day live trial</li><li>Direct onboarding support</li><li>One short feedback conversation</li></ul><p>Ideal for independent restaurants with regular menu changes and 10–25 tables.</p></article></div></section></main><footer class="footer"><b>menuquo</b><span>Better menus, one scan away.</span></footer></div>`}
function login(){return `<main class="auth-wrap"><section class="auth"><a class="brand" href="#landing"><span class="brand-mark">m</span>menuquo</a><h1>Welcome back.</h1><p>Sign in to manage your digital menu.</p><form id="login-form"><label class="field">Email<input type="email" required value="owner@saffrontable.com"></label><label class="field">Password<input type="password" required value="menuquo"></label><button class="btn dark">Continue to dashboard →</button></form><p class="hint">Demo mode — any email and password works.</p></section></main>`}
function nav(page){return `<aside class="sidebar"><a class="brand" href="#dashboard/overview"><span class="brand-mark">m</span>menuquo</a><nav class="side-nav">${[['overview','▦ Overview'],['menu','☰ Menu editor'],['qr','⌘ QR codes'],['settings','⚙ Settings']].map(x=>`<button class="${page===x[0]?'active':''}" data-go="dashboard/${x[0]}">${x[1]}</button>`).join('')}</nav><div class="sidebar-foot"><button class="btn ghost" data-go="landing">← Back to site</button></div></aside>`}
function dashboard(){let page=view.split('/')[1]||'overview';return `<div class="app-layout">${nav(page)}<main class="app-main"><header class="app-header"><h1>${{overview:'Overview',menu:'Menu editor',qr:'QR code studio',settings:'Restaurant settings'}[page]}</h1><span class="restaurant-chip">● ${state.restaurant.name}</span></header><div class="content">${page==='overview'?overview():page==='menu'?editor():page==='qr'?qr():settings()}</div></main></div>`}
function overview(){return `<section class="greeting"><h2>Good morning.</h2><p>Your QR menu is live and ready for guests.</p></section><section class="stat-grid"><article class="stat-card"><small>Total menu scans</small><strong>${state.scanCount}</strong><span class="up">↑ 18% this week</span></article><article class="stat-card"><small>Scans today</small><strong>${state.today}</strong><span class="up">↑ 6 since yesterday</span></article><article class="stat-card"><small>Live menu items</small><strong>${state.menu.reduce((n,c)=>n+c.items.length,0)}</strong><span class="up">All published</span></article></section><section class="panel"><div class="panel-head"><h2>Quick actions</h2><button class="btn ghost" data-go="public">View live menu ↗</button></div><div class="quick"><button data-go="dashboard/menu"><span>☰</span><b>Edit your menu</b><small>Add, update, or hide items.</small></button><button data-go="dashboard/qr"><span>⌘</span><b>Download QR code</b><small>Ready for print or sharing.</small></button><button data-go="dashboard/settings"><span>⚙</span><b>Restaurant settings</b><small>Update your public profile.</small></button></div></section>`}
function editor(){return `<div class="panel-head"><div><h2>Your menu</h2><p style="color:var(--muted);margin:5px 0 0">A visual menu is easier for guests to browse at the table.</p></div><button class="btn" id="new-item">+ Add menu item</button></div>${state.menu.map((c,ci)=>`<section class="category"><div class="category-head"><h3>${c.name}</h3><small>${c.items.length} items</small></div>${c.items.map((x,ii)=>`<div class="menu-item"><img class="menu-thumb" src="${x.image||fallback}" alt=""><div><b>${x.name}</b><small>${x.description}</small></div><b>${money(x.price)}</b><span class="available ${x.available?'':'sold'}">${x.available?'Available':'Sold out'}</span><button class="icon-btn" data-toggle="${ci}-${ii}">↻</button></div>`).join('')}</section>`).join('')}<section class="panel hide" id="item-form"><div class="panel-head"><h2>Add a menu item</h2><button class="icon-btn" id="close-item">×</button></div><form id="add-item-form"><div class="editor-row"><select name="category">${state.menu.map((c,i)=>`<option value="${i}">${c.name}</option>`).join('')}</select><input name="name" required placeholder="Item name"><input name="price" required type="number" placeholder="Price"></div><textarea name="description" placeholder="Short description"></textarea><label class="field">Image URL<input name="image" type="url" placeholder="https://..."></label><button class="btn">Add item</button></form></section>`}
const fallback='https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=200&q=70';
function qr(){let url=`${location.origin}${location.pathname}#public`,img=`https://api.qrserver.com/v1/create-qr-code/?size=420x420&data=${encodeURIComponent(url)}`;return `<div class="qr-layout"><section class="qr-box"><img src="${img}" alt="QR code"><b>${state.restaurant.name}</b><small>Scan to view the menu</small></section><section class="panel"><span class="eyebrow">Your menu link</span><h2 style="margin:14px 0">Ready to print.</h2><p style="color:var(--muted)">This QR code takes guests directly to your live menu.</p><div class="url-box">${url}</div><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:18px"><a class="btn dark" href="${img}" download="menuquo-qr.png">Download PNG</a><button class="btn ghost" data-copy="${url}">Copy link</button></div></section></div>`}
function settings(){return `<section class="panel"><h2>Restaurant settings</h2><p style="color:var(--muted)">Information shown to your guests.</p><form id="settings-form"><label class="field">Restaurant name<input name="name" value="${state.restaurant.name}" required></label><label class="field">Public slug<input name="slug" value="${state.restaurant.slug}" required></label><label class="field">Currency<select name="currency"><option ${state.restaurant.currency==='₹'?'selected':''}>₹</option><option>$</option><option>£</option></select></label><button class="btn">Save changes</button></form></section>`}
function publicMenu(){state.scanCount++;state.today++;save();return `<main class="preview-page"><section class="public-menu"><header class="public-top"><a class="public-brand" href="#landing"><span class="brand-mark">m</span> menuquo</a><button class="btn ghost" data-go="dashboard/overview">Owner view</button></header><section class="menu-hero"><img src="${state.restaurant.hero||initial.restaurant.hero}" alt=""><div class="menu-hero-copy"><span>Welcome to</span><h1>${state.restaurant.name}</h1></div></section><p class="menu-note">A little something for every appetite. Please ask our team about allergens and dietary requirements.</p>${state.menu.map(c=>`<section class="public-section"><h2>${c.name}</h2>${c.items.map(i=>`<article class="public-dish"><img class="dish-image" src="${i.image||fallback}" alt="${i.name}"><div><b>${i.name}</b><small>${i.description}</small>${i.tag?`<span class="dish-tag">${i.tag}</span>`:''}${!i.available?'<small style="color:var(--red);font-weight:700">Currently unavailable</small>':''}</div><b class="price">${money(i.price)}</b></article>`).join('')}</section>`).join('')}<p style="text-align:center;font-size:12px;margin:25px;color:var(--muted)">Powered by Menuquo</p></section></main>`}
function render(){let app=$('#app');app.innerHTML=view==='landing'||view==='sales'?landing():view==='login'?login():view.startsWith('dashboard')?dashboard():view==='public'?publicMenu():landing();bind()}
function bind(){document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-copy]').forEach(e=>e.onclick=async()=>{try{await navigator.clipboard.writeText(e.dataset.copy);toast('Copied to clipboard')}catch{toast('Copy: '+e.dataset.copy)}});let login=$('#login-form');if(login)login.onsubmit=e=>{e.preventDefault();go('dashboard/overview')};let settings=$('#settings-form');if(settings)settings.onsubmit=e=>{e.preventDefault();let d=new FormData(settings);state.restaurant={...state.restaurant,name:d.get('name'),slug:d.get('slug').replace(/\s+/g,'-'),currency:d.get('currency')};save();toast('Restaurant settings saved');render()};let add=$('#add-item-form');if(add)add.onsubmit=e=>{e.preventDefault();let d=new FormData(add);state.menu[+d.get('category')].items.push({name:d.get('name'),price:d.get('price'),description:d.get('description'),image:d.get('image'),available:true});save();toast('Menu item added');render()};let newItem=$('#new-item');if(newItem)newItem.onclick=()=>$('#item-form').classList.remove('hide');let close=$('#close-item');if(close)close.onclick=()=>$('#item-form').classList.add('hide');document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{let[c,i]=b.dataset.toggle.split('-');state.menu[c].items[i].available=!state.menu[c].items[i].available;save();render()})}
addEventListener('hashchange',()=>{view=location.hash.slice(1)||'landing';render()});render();
